  useEffect(()=>{api<{user:User|null}>('/session').then(async r=>{if(r.user)await fetchAccount(r.user,true);}).catch(()=>setError(cloud()?'Could not load encrypted records. Check your connection and reload.':'Local server unavailable. Start Drug Tracker, then reload.')).finally(()=>setLoading(false));},[fetchAccount]);
  useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),5000);return()=>clearTimeout(t);},[toast]);
  async function refresh(){if(!user||doseWork.current)return;const id=user.id,token=generation.current;try{await syncQueue(id);if(token!==generation.current||account.current!==id)return;if(pendingWorkspace.current){try{await cleanupWorkspace(dataRef.current.doses);}catch(e){if(!(e instanceof ApiError)||e.status!==409)throw e;}}const visible=await fetchAccount(user);if(!visible||token!==generation.current||account.current!==id)return;await cleanupWorkspace(visible.doses);if(token!==generation.current||account.current!==id)return;setError('');notify(cloud()?'Synced.':'Saved to this Mac.');}catch(e){if(token===generation.current&&account.current===id)setError((e as Error).message);}}
  useEffect(()=>{const handler=()=>{if(user)void refresh();};window.addEventListener('online',handler);return()=>window.removeEventListener('online',handler);},[user]);
  async function mutate<T>(path:string,body:T,method='PUT'):Promise<T>{
    if(!user)throw new Error('Sign in to record doses.');const owner=user.id,token=generation.current;
    if(account.current!==owner)throw new Error('Account changed. Reload before continuing.');
    try{const result=await api<T>(path,method,body,owner);if(token!==generation.current||account.current!==owner)throw new Error('Account changed. Reload before continuing.');return result;}
    catch(e){if(e instanceof TypeError){if(token!==generation.current||account.current!==owner)throw new Error('Account changed.');await queueMutation(owner,path,body,method);const count=await queueCount(owner);if(token!==generation.current||account.current!==owner)throw new Error('Account changed.');setPending(count);return body;}throw e;}
  }
  function resetAccount(){focusNewDose(null);generation.current++;account.current=null;workspace.current=null;pendingWorkspace.current=null;pendingDoseWrites.current.clear();doseWork.current=false;setBusy(false);setUser(null);setData(emptyData());setProfile(defaultProfile());setDrafts([]);setEditing(null);setConfirmingDose(null);setDeletingDose(null);setChoosingFirstDose(false);setChoosingMoreDose(false);setPending(0);setError('');}
