  const saveFavorite=async (incoming:Favorite)=>{const existing=data.favorites.find(x=>favoriteKey(x)===favoriteKey(incoming));const f=existing?{...incoming,id:existing.id,revision:existing.revision}:incoming;if(!user){setData(v=>({...v,favorites:upsertFavorite(v.favorites,f)}));return;}try{const saved=await mutate(`/favorites/${f.id}`,f);setData(v=>({...v,favorites:upsertFavorite(v.favorites,saved)}));notify('Medication saved.');}catch(e){setError((e as Error).message);throw e;}};
  const removeFavorite=async (f:Favorite)=>{if(!user){setData(v=>({...v,favorites:v.favorites.filter(x=>x.id!==f.id)}));return;}try{await mutate(`/favorites/${f.id}`,{revision:f.revision},'DELETE');setData(v=>({...v,favorites:v.favorites.filter(x=>x.id!==f.id)}));}catch(e){setError((e as Error).message);throw e;}};
  async function saveEdit(confirm=false){if(editing)await saveDose(editing,confirm?'confirm':'edit');}
  async function saveCheckin(entry:Checkin){if(!user){setAuth(true);throw new Error('Unlock to save a check-in.');}const saved=await mutate(`/checkins/${entry.id}`,entry);setData(v=>({...v,checkins:[...v.checkins.filter(c=>c.id!==saved.id),saved]}));notify('Check-in saved.');}
  async function removeCheckin(entry:Checkin){await mutate(`/checkins/${entry.id}`,{revision:entry.revision},'DELETE');setData(v=>({...v,checkins:v.checkins.filter(c=>c.id!==entry.id)}));notify('Check-in deleted.');}
  const {actual,planned,drafts:activeDrafts}=partitionDoseEntries(data.doses,drafts);
  const actualIds=new Set(actual.map(d=>d.id));
